-- data/techniques.json 에서 생성 (scripts/techniques-to-sql.mjs). 직접 고치지 말고 JSON 을 고친다.
-- 포지션 9개 · slug 기준 upsert
insert into public.positions (slug, name_ko, name_en, sort_order)
values
  ('standing', '스탠딩', 'Standing', 1),
  ('closed-guard', '클로즈드 가드', 'Closed Guard', 2),
  ('open-guard', '오픈 가드', 'Open Guard', 3),
  ('half-guard', '하프가드', 'Half Guard', 4),
  ('passing', '패스', 'Guard Passing', 5),
  ('side-control', '사이드 컨트롤', 'Side Control', 6),
  ('mount', '마운트', 'Mount', 7),
  ('back-control', '백 컨트롤', 'Back Control', 8),
  ('turtle', '터틀', 'Turtle', 9)
on conflict (slug) do update set
  name_ko    = excluded.name_ko,
  name_en    = excluded.name_en,
  sort_order = excluded.sort_order;

-- 기술 87개 · slug 기준 upsert
insert into public.techniques (position_id, slug, name_ko, name_en, aliases, steps, is_reviewed, source, sort_order)
select p.id, t.slug, t.name_ko, t.name_en, t.aliases, t.steps, t.is_reviewed, t.source, t.sort_order
from (values
  ('standing', 'breakfall', '낙법', 'Breakfall', array['뒤낙법','옆낙법','우케미']::text[], array['턱을 당겨 뒤통수가 바닥에 닿지 않게 한다','엉덩이 → 등 순서로 둥글게 닿으며 넘어진다','닿는 순간 팔을 45도로 펴서 손바닥으로 바닥을 친다(옆낙법은 한 팔)','무릎을 굽혀 세우고 바로 일어날 수 있게 자세를 모은다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: 일반 기초', 1),
  ('standing', 'grip-fighting', '그립 파이팅 (기본 그립)', 'Grip Fighting (Collar & Sleeve)', array['그립 싸움','깃 소매 잡기']::text[], array['한 손은 상대 깃(칼라), 반대 손은 같은 쪽 소매 끝을 잡는다','상대가 내 깃을 잡으면 손목을 돌리고 팔을 당겨 바로 떼어낸다','내 그립은 팔꿈치를 몸에 붙여 짧게 유지한다','그립을 먼저 잡은 쪽이 테이크다운이나 가드 풀링을 시작한다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing', 2),
  ('standing', 'pulling-guard', '가드 풀링', 'Pulling Guard', array['풀 가드','가드 당기기']::text[], array['깃과 소매(또는 손목)를 잡는다','한 발을 상대 골반에 밟고 엉덩이를 뒤로 떨어뜨리며 상대를 당긴다','밟은 발 반대 다리를 상대 허리에 감는다','양 다리를 상대 등 뒤에서 걸어 클로즈드 가드를 완성한다(또는 바로 오픈 가드)']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-guard/bottom 1위', 3),
  ('standing', 'double-leg-takedown', '더블 레그 테이크다운', 'Double Leg Takedown', array['더블렉','더블 레그']::text[], array['자세를 낮추고 앞발을 상대 다리 사이로 깊게 내딛는다','양팔로 상대 무릎 뒤를 감아 당긴다','머리를 상대 옆구리에 붙이고 가슴을 앞으로 민다','뒷발을 끌어와 옆으로 돌며 눕히고 바로 사이드로 올라간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: 일반', 4),
  ('standing', 'single-leg-takedown', '싱글 레그 테이크다운', 'Single Leg Takedown', array['싱글렉','싱글 레그']::text[], array['앞발을 내딛으며 상대 한쪽 다리를 양팔로 안는다','머리를 상대 가슴 안쪽에 붙여 길로틴을 막는다','잡은 다리를 내 허벅지 사이에 끼우고 일어선다','다리를 바깥으로 밀거나 걸어 넘어뜨리고 패스 자세를 잡는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: 일반', 5),
  ('standing', 'o-soto-gari', '오소토가리', 'O Soto Gari', array['오소토','밭다리 후리기']::text[], array['깃과 소매를 잡고 당겨 상대 뒤꿈치에 체중이 실리게 한다','당기는 쪽 발을 상대 발 옆에 깊게 내딛는다','반대 다리를 상대 다리 바깥쪽으로 크게 휘둘러 올린다','다리를 뒤로 후리며 상체는 아래로 눌러 넘어뜨린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: 일반', 6),
  ('standing', 'o-uchi-gari', '오우치가리', 'O Uchi Gari', array['안다리 후리기','인사이드 트립']::text[], array['깃과 소매를 잡고 상대를 앞으로 당겨 한쪽 발에 체중을 싣게 한다','그 발 안쪽으로 내 발을 넣어 종아리를 건다','건 다리를 뒤로 후리며 상체는 앞으로 민다','넘어가면 다리 사이로 들어가 패스 자세를 잡는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph Inside Trip', 7),
  ('standing', 'seoi-nage', '세오이나게', 'Seoi Nage', array['업어치기','세오이']::text[], array['깃과 소매를 잡고 상대를 앞으로 당긴다','소매 쪽으로 돌아 들어가며 등을 상대 가슴에 붙인다','무릎을 굽혀 엉덩이를 상대보다 낮게 둔다','다리를 펴며 상체를 숙여 어깨 위로 넘긴다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: 일반', 8),
  ('standing', 'arm-drag-standing', '암 드래그 (스탠딩)', 'Arm Drag to Back (Standing)', array['암드랙','팔 끌기']::text[], array['상대 한 손목을 같은 쪽 손으로 잡는다','반대 손으로 그 팔의 삼두(팔꿈치 위)를 잡아 내 옆으로 끌어 당긴다','당기며 상대 옆으로 빠져 등 뒤로 돌아 들어간다','허리를 안거나(바디락) 시트벨트를 잡아 백을 잡는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §1.7 · BJJGraph standing-guard/bottom', 9),
  ('standing', 'sprawl', '스프롤 (테이크다운 방어)', 'Sprawl', array['스프럴','테이크다운 디펜스']::text[], array['상대가 다리로 들어오면 양 다리를 뒤로 쭉 빼고 엉덩이를 바닥 쪽으로 낮춘다','가슴과 체중을 상대 등 위로 실어 누른다','한 팔은 상대 겨드랑이 아래(언더훅)나 목 앞(프론트 헤드락)으로','상대가 손을 놓으면 옆으로 돌아 백이나 터틀 탑으로 간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §9.1 · BJJGraph', 10),
  ('standing', 'standing-guillotine', '길로틴 초크 (스탠딩)', 'Guillotine Choke (Standing)', array['길로틴','스탠딩 길로틴']::text[], array['상대 머리가 아래로 숙여진 순간(테이크다운 시도 등) 한 팔을 목 앞으로 감는다','감은 손을 반대 손으로 잡아 그립을 만든다(팔꿈치는 가슴에 붙임)','엉덩이를 뒤로 빼고 가슴을 펴서 목을 당긴다','앉아서 끝낼 땐 뒤로 눕지 말고 몸을 옆으로 틀어 체중으로 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.6 ''뒤로 젖히지 말 것''', 11),
  ('closed-guard', 'closed-guard-basics', '클로즈드 가드 (자세 · 포스처 깨기)', 'Closed Guard (Basics & Breaking Posture)', array['풀 가드','클로즈 가드','가드 유지']::text[], array['양 다리를 상대 허리 뒤에서 교차해 발목을 잠근다','무릎을 조이고 다리로 당겨 상대 가슴을 내 쪽으로 무너뜨린다(포스처 깨기)','한 손은 목 뒤, 한 손은 소매나 깃을 잡는다 — 목 뒤 그립은 손목을 걸어 한쪽으로 모은다','상대 팔이 내 가슴을 밀면 안쪽에서 바깥으로 쳐내 바닥에 짚게 만든다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.1', 1),
  ('closed-guard', 'scissor-sweep', '시저 스윕', 'Scissor Sweep', array['가위 스윕']::text[], array['깃과 소매(또는 팔꿈치)를 잡고 상대를 앞으로 당긴다','가드를 열고 엉덩이를 살짝 빼서 한 무릎을 상대 배 앞에 가로로 댄다(니 쉴드)','반대 다리는 바닥 가까이 내려 상대 무릎 바깥에 건다','위 다리는 밀고 아래 다리는 당기며(가위) 소매를 당겨 넘기고 마운트로 올라간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 · BJJGraph closed-guard/bottom 1위', 2),
  ('closed-guard', 'hip-bump-sweep', '힙 범프 스윕', 'Hip Bump Sweep', array['시트업 스윕','힙범프']::text[], array['상대가 상체를 세우고 내 가슴을 누를 때 — 가드를 풀고 한 손으로 뒤 바닥을 짚으며 앉아 일어난다','반대 팔을 상대 어깨 위로 넘겨 삼두(팔 뒤)를 감싼다','엉덩이를 높이 들어 상대 어깨를 옆으로 친다','넘어가면 다리를 180도 돌려 마운트. 상대가 손을 짚으면 기무라, 앞으로 밀면 길로틴으로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 (힙범프 → 기무라 → 길로틴 체인)', 3),
  ('closed-guard', 'flower-sweep', '플라워 스윕 (펜듈럼)', 'Flower / Pendulum Sweep', array['펜듈럼 스윕','플라워']::text[], array['한쪽 소매(또는 손목)와 같은 쪽 바지 무릎 안쪽을 잡는다','가드를 열고 소매 쪽 다리를 상대 겨드랑이 쪽으로 높게 올린다','반대 다리는 바닥 가까이 크게 돌린다(진자처럼) — 반대 팔로 상대 다리 아래를 안으면 더 강하다','올린 다리로 겨드랑이를 치며 돌려 넘기고 팔을 잡은 채 마운트로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 · BJJGraph', 4),
  ('closed-guard', 'cross-collar-choke-guard', '크로스 칼라 초크 (가드)', 'Cross Collar Choke from Closed Guard', array['크로스 초크','십자 조르기','칼라 초크']::text[], array['한 손을 상대 깃 깊숙이 넣는다(엄지 안쪽, 손바닥 위로)','반대 손은 첫 손 위로 교차해 반대 깃을 잡는다','상대를 다리로 당기며 팔꿈치를 아래로 떨어뜨린다','손목을 비틀어 양쪽 목 옆을 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 4위)', 5),
  ('closed-guard', 'closed-guard-armbar', '클로즈드 가드 암바', 'Armbar from Closed Guard', array['암바','주짓수 암바']::text[], array['상대 한 팔을 가슴에 붙여 손목을 잡고, 반대 손은 그 팔의 삼두를 잡아 중앙으로 당긴다','같은 쪽 발을 상대 골반에 밟고 엉덩이를 돌려 몸을 상대와 직각으로 만든다','반대 다리를 상대 등 위로 올려 머리를 누르고 자세를 낮춘다','다리를 모아 무릎을 조이고 엉덩이를 들어 팔꿈치를 편다(엄지는 위로)']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.3', 6),
  ('closed-guard', 'triangle-choke', '트라이앵글 초크', 'Triangle Choke', array['트라이앵글','삼각 조르기']::text[], array['상대 한 손목을 잡아 한 팔은 안쪽, 한 팔은 바깥쪽이 되게 만든다','가드를 열고 안쪽 팔 쪽 다리를 상대 목 뒤로 올리고 반대 다리는 겨드랑이 아래로','그 발목을 반대 무릎 뒤에 걸어 삼각형을 만들고, 두 손으로 머리를 당겨 자세를 낮춘다','목 위 다리 반대쪽으로 몸을 틀어 각도를 만들고 안쪽 팔을 얼굴 반대로 넘긴 뒤 다리를 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.3 (각도 규칙) · BJJGraph', 7),
  ('closed-guard', 'kimura-guard', '기무라 (가드)', 'Kimura from Closed Guard', array['키무라','기무라 락']::text[], array['상대 손목을 잡고 반대 팔로 윗팔을 감아 내 손목을 잡는다(8자 그립)','엉덩이를 옆으로 빼서 상대와 직각에 가깝게 눕는다','팔꿈치를 상대 어깨에 눌러 붙인 채 다리로 상대 몸을 묶는다','상대 손이 등 뒤 머리 쪽으로 가게 돌려 탭을 받는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 · §11.3', 8),
  ('closed-guard', 'omoplata', '오모플라타', 'Omoplata', array['오모플라따']::text[], array['상대 한 팔의 삼두를 잡고 머리를 당겨 포스처를 깬다','가드를 열고 그 팔 쪽으로 엉덩이를 빼며 같은 쪽 다리를 상대 팔 위 · 등 뒤로 넘긴다','발목을 상대 목에 걸고 반대 다리를 모아 어깨를 감싼다','앉아 올라오며 상대 허리를 잡아 못 일어나게 하고 엉덩이를 앞으로 밀어 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.3 (골반 눕히기 디테일)', 9),
  ('closed-guard', 'arm-drag-guard', '암 드래그 → 백 테이크 (가드)', 'Arm Drag to Back from Closed Guard', array['암드랙','팔 끌어 백 잡기']::text[], array['상대 한 손목을 잡고 반대 손으로 삼두를 잡는다(투 온 원)','다리로 상대를 당겨 가슴을 붙이고 팔을 내 몸 반대쪽으로 끌어 넘긴다','가드를 풀고 옆으로 일어나며 반대 팔로 상대 등 뒤 겨드랑이를 잡는다','훅을 넣고 시트벨트를 잡아 백 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 · §8.1', 10),
  ('closed-guard', 'guillotine-guard', '길로틴 초크 (가드)', 'Guillotine from Closed Guard', array['가드 길로틴']::text[], array['상대 머리가 내 가슴 쪽으로 숙여질 때(힙 범프를 막으려 밀 때 등) 한 팔을 목 앞으로 감는다','감은 손을 반대 손으로 잡아 그립을 만들고 팔꿈치를 몸에 붙인다','상대 머리가 있는 쪽으로 몸을 틀고 다리를 감아 못 빠지게 한다','뒤로 젖히지 말고 가슴을 펴며 체중으로 목을 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §9.4 · §11.6', 11),
  ('open-guard', 'technical-stand-up', '테크니컬 스탠드업', 'Technical Stand-Up', array['테크니컬 겟업','기본 일어서기']::text[], array['앉은 자세에서 한 손은 뒤 바닥을 짚고 반대 손은 앞을 막는다(프레임)','짚은 손 반대 발을 세우고 엉덩이를 들어 올린다','세운 발과 손 사이로 반대 다리를 빼서 뒤로 보낸다','무릎을 펴고 일어서며 앞 손은 계속 상대를 막는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom · 기초', 1),
  ('open-guard', 'shrimp-hip-escape', '쉬림프 (힙 이스케이프)', 'Shrimp / Hip Escape', array['새우','힙 이스케이프']::text[], array['등을 대고 누워 한 발로 바닥을 민다','같은 쪽 어깨로 돌아 누우며 엉덩이를 뒤로 뺀다','팔꿈치와 손으로 상대를 밀어(프레임) 생긴 공간을 유지한다','무릎을 상대와 나 사이로 넣어 가드를 되찾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §1.4 · 기초', 2),
  ('open-guard', 'collar-sleeve-guard', '칼라 슬리브 가드', 'Collar Sleeve Guard', array['깃 소매 가드']::text[], array['한 손은 상대 깃, 반대 손은 같은 쪽 소매를 잡는다','소매 쪽 발은 상대 이두(팔 안쪽)에 대고, 반대 발은 골반에 댄다','깃을 당기고 발로 밀어 상대 자세를 무너뜨린다','상대가 무너지는 쪽으로 트라이앵글 · 오모플라타 · 스윕으로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom (기 1위)', 3),
  ('open-guard', 'de-la-riva-guard', '데라히바 가드', 'De La Riva Guard', array['DLR','데라']::text[], array['상대 한쪽 다리 바깥으로 내 다리를 감아 발을 상대 골반 앞에 건다','같은 쪽 손으로 발목(또는 바지 끝)을 잡는다','반대 발은 상대 허벅지나 골반에 대어 거리를 지킨다','반대 손으로 소매나 깃을 잡아 상체를 컨트롤한다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.3 · BJJGraph', 4),
  ('open-guard', 'de-la-riva-sweep', '데라히바 스윕', 'De La Riva Sweep', array['DLR 스윕']::text[], array['데라히바 훅 · 발목 · 소매 그립을 잡는다','골반에 댄 발로 밀며 발목을 당겨 상대를 한 발에 서게 만든다','훅 다리로 상대 다리를 들어 올리며 소매를 당긴다','넘어가면 발목을 놓지 않고 따라 올라가 패스 자세로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph de-la-riva-guard/bottom 1위', 5),
  ('open-guard', 'spider-guard', '스파이더 가드', 'Spider Guard', array['스파이더']::text[], array['양 소매를 잡고 상대 팔이 펴지게 민다','양 발바닥을 상대 이두(팔 안쪽)에 댄다','한쪽은 밀고 한쪽은 당겨 상대 균형을 흔든다','상대가 무너지는 쪽으로 스윕이나 트라이앵글로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph spider-guard', 6),
  ('open-guard', 'spider-sweep', '스파이더 스윕', 'Spider Sweep', array['스파이더 가드 스윕']::text[], array['스파이더 가드에서 한쪽 발을 이두에서 떼어 상대 무릎 안쪽을 건다','반대 발은 이두를 계속 밀어 팔을 뻗게 한다','건 다리로 무릎을 당기고 소매는 반대로 당겨 넘긴다','소매를 놓지 않고 일어나 패스 자세로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph spider-guard/bottom 1위', 7),
  ('open-guard', 'lasso-guard', '라쏘 가드', 'Lasso Guard', array['라소 가드','라쏘']::text[], array['한쪽 소매를 잡고 같은 쪽 발을 상대 팔 바깥에서 안으로 감아 넣는다(올가미)','발을 상대 겨드랑이 아래까지 깊게 넣는다','반대 발은 상대 이두나 골반에 대어 거리를 지킨다','소매를 당기며 라쏘 발로 상대를 돌려 균형을 뺏는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lasso-guard', 8),
  ('open-guard', 'lasso-sweep', '라쏘 스윕', 'Lasso Sweep', array['라쏘 가드 스윕']::text[], array['라쏘를 깊게 걸고 반대 손으로 같은 쪽 발목이나 바지를 잡는다','반대 발로 상대 무릎 안쪽을 밀거나 건다','라쏘 다리로 팔을 들어 올리며 발목을 당겨 넘긴다','넘어가면 라쏘를 풀고 위로 올라간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lasso-guard/bottom 1위', 9),
  ('open-guard', 'butterfly-guard', '버터플라이 가드', 'Butterfly Guard', array['버터플라이','나비 가드']::text[], array['앉은 자세에서 양 발을 상대 허벅지 안쪽에 훅처럼 넣는다','무릎은 바깥으로 벌리고 발등으로 들어 올린다(무릎을 모으지 않는다)','상체를 세우고 언더훅이나 깃을 잡아 가슴을 붙인다','엉덩이를 상대 가까이 당겨 거리를 없애고 스윕을 노린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.1', 10),
  ('open-guard', 'butterfly-sweep', '버터플라이 스윕', 'Butterfly Sweep', array['훅 스윕']::text[], array['버터플라이 가드에서 한쪽 언더훅을 잡고 반대 손은 소매나 손목을 잡는다','언더훅 쪽으로 몸을 기울이며 상대 체중을 받는다','같은 쪽 훅 발로 상대 다리를 들어 올리며 옆으로 눕는다','굴러 넘어가 위로 올라온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-guard/bottom 1위', 11),
  ('open-guard', 'elevator-sweep', '엘리베이터 스윕', 'Elevator Sweep', array['엘레베이터 스윕']::text[], array['상대가 무릎 서서 들어올 때 한 발을 상대 허벅지 안쪽에 훅으로 넣는다','반대 다리는 상대 다리 바깥을 감거나 바닥에 둔다','상대 팔이나 깃을 당기며 훅 발로 다리를 위로 들어 올린다','들린 쪽으로 넘기고 위로 올라온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-guard/bottom 2위', 12),
  ('open-guard', 'tripod-sweep', '트라이포드 스윕', 'Tripod Sweep', array['삼각대 스윕']::text[], array['상대 한쪽 소매와 같은 쪽 발목을 잡는다','발목 잡은 쪽 발을 상대 골반에 대고 민다','반대 발로 상대 반대 다리 뒤(오금)를 걸어 당긴다','밀고 당기며 뒤로 눕히고 발목을 놓지 않고 일어나 패스 자세로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom', 13),
  ('open-guard', 'sickle-sweep', '시클 스윕', 'Sickle Sweep', array['낫 스윕']::text[], array['트라이포드와 같은 그립(소매 · 발목)에서 시작한다','골반에 댄 발을 떼어 상대 반대 발목 바깥을 낫처럼 건다','반대 발은 상대 무릎이나 골반을 밀어 낸다','걸고 밀며 상대를 옆으로 넘기고 일어난다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom', 14),
  ('half-guard', 'half-guard-basics', '하프가드 (자세 · 프레임)', 'Half Guard (Basics & Frames)', array['하프','반 가드']::text[], array['상대 한쪽 다리를 내 양 다리로 감아 발목을 잠근다','감은 다리 쪽으로 옆으로 돌아 눕는다 — 등이 바닥에 평평하면 진다','위쪽 팔뚝은 상대 목, 아래 팔뚝은 골반에 대어 프레임을 만든다(손바닥이 아니라 뼈로)','밀기 전에 먼저 브릿지로 상대 체중을 띄운 뒤 엉덩이를 빼서 공간을 만든다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.1~3.2', 1),
  ('half-guard', 'knee-shield-half-guard', '니 쉴드 하프가드', 'Knee Shield Half Guard', array['제트 가드','Z 가드','니실드']::text[], array['하프가드에서 위쪽 무릎을 상대 배나 골반 앞에 가로로 세운다(낮은 니 쉴드)','아래 다리는 상대 다리를 계속 감아 둔다','같은 쪽 손은 내 무릎, 반대 손은 상대 이두를 잡아 거리를 지킨다','상대가 무릎을 밀어 치우면 그 팔을 따라 들어가 언더훅으로 바꾼다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.3 · BJJGraph half-guard/bottom 1위', 2),
  ('half-guard', 'half-guard-underhook', '하프가드 언더훅 잡기', 'Winning the Underhook from Half Guard', array['언더훅 싸움','언더훅']::text[], array['팔로 먼저 뻗지 말고 무릎을 들어 올려 상대 몸을 위로 밀어 공간을 만든다','생긴 공간으로 팔을 넣어 상대 겨드랑이 아래를 감는다','손은 상대 등 위가 아니라 골반 가까이, 팔꿈치는 몸에 붙여 짧게 잡는다','언더훅을 잡으면 머리를 상대 겨드랑이 밑으로 빼고 스윕이나 백 테이크로 간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.4 ''다리로 공간을 만들고 팔이 채운다''', 3),
  ('half-guard', 'half-guard-underhook-sweep', '하프가드 언더훅 스윕 (올드 스쿨)', 'Half Guard Underhook Sweep (Old School)', array['언더훅 스윕','올드 스쿨 스윕']::text[], array['하프가드에서 언더훅을 잡고 옆으로 돌아 눕는다','머리를 상대 겨드랑이 아래로 넣어 자세를 낮춘다','언더훅 팔로 상대 다리를 안아 내리고(또는 발목을 잡고) 중심을 뺏는다','앞으로 밀며 올라와 탑으로 간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.5 · BJJGraph', 4),
  ('half-guard', 'half-guard-back-take', '하프가드 백 테이크', 'Back Take from Half Guard', array['하프에서 백 잡기']::text[], array['언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로 뺀다','무릎을 세워 상대 등 뒤로 돌아 올라온다(도그파이트)','한 손으로 허리띠나 허리를 잡고 가슴을 상대 등에 붙인다','훅을 넣고 시트벨트를 잡아 백 컨트롤을 완성한다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.5 · BJJGraph 3위', 5),
  ('half-guard', 'half-guard-recovery', '하프가드에서 가드 회복', 'Half Guard to Full Guard Recovery', array['가드 리커버리','풀 가드 복귀']::text[], array['상대 목과 골반에 프레임을 만든다','브릿지 → 엉덩이 빼기(쉬림프)를 한 번이 아니라 두 번 한다','감아 둔 다리 쪽 무릎을 상대 배 앞으로 가져온다','반대 다리를 상대 허리 위로 넘겨 클로즈드 가드나 버터플라이로 돌아온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.2 ''더블 힙 이스케이프'' · BJJGraph', 6),
  ('half-guard', 'deep-half-guard', '딥 하프가드', 'Deep Half Guard', array['딥 하프']::text[], array['하프가드에서 상대 다리 아래로 깊게 파고들어 허벅지가 내 가슴 위에 오게 한다','감은 다리 쪽 팔로 상대 허벅지를 안고 머리는 상대 다리 아래로 숨긴다','반대 손으로 상대 발목이나 허리띠를 잡아 자세를 고정한다','상대 다리를 들어 올리며 돌아 위로 올라온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/bottom', 7),
  ('half-guard', 'kimura-half-guard', '기무라 (하프가드)', 'Kimura from Half Guard', array['하프 기무라','기무라 트랩']::text[], array['상대가 내 머리를 누르거나 바닥을 짚은 손목을 잡는다','반대 팔로 상대 윗팔을 감아 내 손목을 잡는다(8자 그립)','옆으로 돌아 팔꿈치를 몸에 붙이고 상대 어깨를 바닥 쪽으로 누른다','바로 안 꺾이면 스윕이나 백 테이크로 잇는다(기무라 트랩)']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.6 · §11.3', 8),
  ('passing', 'posture-in-closed-guard', '클로즈드 가드 안에서 자세 잡기', 'Posture inside Closed Guard', array['포스처','가드 안 자세']::text[], array['허리를 펴고 머리를 세워 상대가 당기지 못하게 한다','양손은 상대 갈비(골반 아님)를 누르거나 깃 · 허리띠를 잡는다','팔꿈치를 몸에 붙여 암바 · 기무라에 팔을 내주지 않는다','무릎을 넓게 벌려 베이스를 만든 뒤 가드 열기로 간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 · BJJGraph closed-guard/top 1위', 1),
  ('passing', 'closed-guard-break-knee', '가드 열기 (무릎 쐐기)', 'Closed Guard Break (Knee Wedge)', array['가드 브레이크','가드 오픈']::text[], array['자세를 세운 채 한 무릎을 상대 꼬리뼈 아래에 쐐기처럼 넣는다','뒤로 앉으며 상대 발목 잠금에 압력을 건다','한 손으로 상대 무릎을 눌러 다리를 연다 — 반대 팔은 상대 허벅지를 계속 막는다(두 팔을 동시에 뒤로 빼지 않는다)','열리면 무릎을 다리 사이로 넣어 니슬라이스로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 ''웨지 패스''', 2),
  ('passing', 'standing-guard-break', '스탠딩 가드 브레이크', 'Standing Closed Guard Break', array['서서 가드 열기']::text[], array['상대 양 이두를 바닥에 눌러 고정하고 한 발씩 세워 일어선다','허리를 펴고 뒤로 한 발 물러나며 상대 허벅지 안쪽을 양손으로 누른다','다리가 풀리면 한 다리를 내 허벅지 사이에 끼우거나 어깨에 걸어 컨트롤한다','바로 니슬라이스나 토레안도로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 ''스탠딩 패스''', 3),
  ('passing', 'knee-slice-pass', '니슬라이스 패스', 'Knee Slice Pass', array['니컷','니스루','니 스플릿','knee cut']::text[], array['한 무릎(정강이)을 상대 허벅지 안쪽 위에 올리고 뒷발은 세워 미는 힘을 만든다','같은 쪽 팔로 언더훅(또는 깃)을 잡아 상대 어깨를 바닥에 붙인다','정강이를 바닥까지 미끄러뜨리며 다리를 끝까지 빼낸다 — 다리가 다 빠지기 전에 골반을 돌리지 않는다','빠지면 골반을 돌려 가슴을 붙이고 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.2 (안전 규칙) · BJJGraph 거의 모든 가드에서 상위', 4),
  ('passing', 'toreando-pass', '토레안도 패스', 'Toreando Pass', array['불 패스','토레아도','투우사 패스']::text[], array['양손으로 상대 무릎 뒤 또는 바지 끝을 잡는다','한쪽 무릎을 바닥으로 눌러 ''죽이고'' 반대쪽으로 다리를 밀어 넘긴다','발을 옆으로 옮겨 상대 옆으로 돌아 들어간다','어깨를 가슴에 떨어뜨리고 머리를 컨트롤해 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6 · BJJGraph open-guard/top 1위', 5),
  ('passing', 'leg-drag', '레그 드래그', 'Leg Drag Pass', array['렉 드래그','다리 끌기']::text[], array['상대 한쪽 발목(또는 바지 끝)을 잡는다','그 다리를 내 반대쪽 엉덩이 옆으로 끌어와 허벅지 사이에 끼운다','같은 쪽 무릎을 상대 엉덩이 옆에 붙여 돌지 못하게 막는다','상체를 숙여 가슴을 누르며 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/top 3위', 6),
  ('passing', 'double-under-pass', '더블 언더 패스 (스택)', 'Double Under / Stack Pass', array['스택 패스','더블언더']::text[], array['양팔을 상대 다리 아래로 넣고 손을 모아 허리띠나 깃을 잡는다','상대 엉덩이를 들어 내 허벅지 위에 얹는다(스택)','어깨로 다리를 머리 쪽으로 눌러 공간을 뺏는다','한쪽으로 돌며 다리를 빼내고 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6 · BJJGraph', 7),
  ('passing', 'over-under-pass', '오버 언더 패스', 'Over Under Pass', array['오버언더']::text[], array['한 팔은 상대 다리 아래(언더), 반대 팔은 다리 위(오버)로 감는다','머리를 오버 쪽 상대 엉덩이 옆에 붙이고 가슴을 낮춘다','오버 쪽 다리를 내 다리 사이에 끼우고 발끝으로 서서 언더 쪽 다리를 어깨로 든다','다리를 바닥에 눌러 두고 돌아 나와 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6', 8),
  ('passing', 'long-step-pass', '롱 스텝 패스', 'Long Step Pass', array['롱스텝']::text[], array['상대 무릎과 반대 어깨(또는 깃)를 잡아 거리를 잡는다','한 다리를 뒤로 길게 뻗으며 엉덩이를 바닥 쪽으로 낮춘다(스프롤)','상대 다리를 바닥으로 눌러 훅이 걸리지 않게 한다','뻗은 다리를 돌려 상대 옆으로 들어가 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 여러 가드 top 공통', 9),
  ('passing', 'half-guard-pass', '하프가드 패스 (크로스페이스 · 언더훅)', 'Half Guard Pass (Crossface & Underhook)', array['하프 패스','크로스페이스 패스','언더훅 패스']::text[], array['언더훅을 먼저 잡고 상대 어깨를 바닥에 눌러 평평하게 만든다','반대 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','내 자유로운 다리로 상대 먼 쪽 다리를 걸어 눌러 가드 회복을 막는다','감긴 다리를 빼내고 가슴을 붙여 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.1 (언더훅 → 눕히기 → 머리 → 먼 다리 → 빼기)', 10),
  ('passing', 'smash-pass', '스매시 패스', 'Smash Pass', array['스매쉬 패스','하프 스매시']::text[], array['하프가드 위에서 상대 니 쉴드 무릎을 바닥으로 누른다','상대 양 무릎이 겹치게 체중으로 눌러 골반을 비튼다','팔꿈치를 바닥에 가깝게 두고 머리로 상대 가슴을 누른다','감긴 다리를 빼며 돌아 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.3 · BJJGraph half-guard/top 2위', 11),
  ('passing', 'butterfly-pass', '버터플라이 패스', 'Butterfly Guard Pass', array['버터플라이 가드 패스']::text[], array['양 훅에 체중을 똑같이 싣고 걸어 들어가지 않는다 — 한쪽을 고른다','한 손으로 상대 한쪽 훅(발)을 바닥에 밀어 내린다','반대쪽 엉덩이를 뒤로 넓게 빼서 남은 훅이 들지 못하게 한다','하프가드로 내려앉아 니슬라이스로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.1', 12),
  ('side-control', 'side-control-maintain', '사이드 컨트롤 유지', 'Side Control (Crossface & Underhook)', array['크로스페이스','사이드 잡기']::text[], array['무릎을 상대 옆구리에 붙이고 가슴으로 상대 가슴을 누른다','머리 쪽 팔은 상대 목 아래로 넣어 먼 겨드랑이를 잡고 어깨로 턱을 밀어 얼굴을 돌린다(크로스페이스)','반대 팔은 상대 가까운 팔을 옆구리에 눌러 언더훅을 못 잡게 한다','상대가 무릎을 넣으려 하면 골반을 바닥에 떨어뜨려 막는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.1', 1),
  ('side-control', 'side-control-escape', '사이드 이스케이프 (프레임 · 쉬림프)', 'Side Control Escape (Frame & Shrimp)', array['힙 이스케이프','쉬림프']::text[], array['팔뚝 뼈로 상대 목과 골반에 프레임을 만든다','먼저 브릿지로 상대를 띄우고 프레임으로 공간을 지킨다','엉덩이를 빼서(쉬림프) 공간을 만든다 — 한 번에 안 되면 두 번','무릎을 상대와 나 사이로 넣어 가드를 되찾거나 언더훅을 잡고 일어난다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.4 · BJJGraph side-control/bottom', 2),
  ('side-control', 'side-to-mount', '사이드에서 마운트 가기', 'Side Control to Mount', array['니 슬라이드 마운트','마운트 전환']::text[], array['크로스페이스로 상대 머리를 반대쪽으로 돌려 둔다','골반 쪽 무릎을 상대 배 위로 미끄러뜨린다','반대 손으로 상대 무릎이나 허벅지를 눌러 다리로 걸지 못하게 한다','무릎이 반대편 바닥에 닿으면 체중을 낮춰 마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.3 · BJJGraph side-control/top 1위', 3),
  ('side-control', 'knee-on-belly', '니 온 밸리', 'Knee on Belly', array['니온벨리','무릎 누르기']::text[], array['깃과 바지(또는 허리띠)를 잡는다','가까운 쪽 무릎을 상대 배 위에 올리고 발끝은 바닥에 닿지 않게 한다','반대 다리는 펴서 발로 바닥을 밀며 중심을 잡는다','깃을 위로 당기고 무릎으로 눌러 압박하며 암바 · 초크 · 마운트를 노린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-on-belly', 4),
  ('side-control', 'knee-on-belly-escape', '니 온 밸리 이스케이프', 'Knee on Belly Escape', array['니온벨리 탈출']::text[], array['상대 무릎을 손으로 치우려 하지 말고 팔뚝으로 무릎과 골반에 프레임을 만든다','상대 쪽으로 돌며 엉덩이를 빼서 무릎을 떨어뜨린다','가까운 무릎을 상대와 나 사이로 넣는다','가드로 돌아오거나 터틀로 돌아 일어난다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-on-belly/bottom', 5),
  ('side-control', 'north-south', '노스사우스', 'North-South', array['노스 사우스','69 포지션']::text[], array['사이드에서 머리 쪽 팔을 상대 겨드랑이 아래로, 반대 팔은 상대 골반으로 옮긴다','상대 손이 내 골반을 막으면 그 위로 체중을 떨어뜨려 눌러 둔다','다리를 상대 머리 쪽으로 걸어 돌며 가슴으로 상대 가슴을 누른다','엉덩이를 너무 상대 가슴 위로 올리지 않고 체중을 뒤로 둔 채 기무라 · 초크를 노린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.3', 6),
  ('side-control', 'kesa-gatame', '케사가타메 (스카프 홀드)', 'Kesa Gatame (Scarf Hold)', array['스카프 홀드','곁누르기']::text[], array['사이드에서 상대 가까운 팔을 내 겨드랑이에 끼워 잡는다','엉덩이를 상대 옆구리에 붙이고 돌아앉으며 반대 팔로 상대 머리를 감는다','다리를 앞뒤로 넓게 벌려 베이스를 만든다','상대 어깨를 가슴으로 눌러 고정하고 암락이나 마운트 전환을 노린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/top', 7),
  ('side-control', 'americana-side', '아메리카나 (사이드)', 'Americana from Side Control', array['키락','아메리카나']::text[], array['상대 손목을 바닥에 눌러 팔꿈치가 90도로 굽혀지게 한다(손바닥은 위로)','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 몸에 붙이고 손목은 바닥에 붙여 둔다','손목을 바닥에 끌며 팔꿈치를 위로 들어 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.4', 8),
  ('side-control', 'kimura-side', '기무라 (사이드)', 'Kimura from Side Control', array['사이드 키무라']::text[], array['상대가 내 목을 밀 때 그 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 머리 쪽으로 돌아 무릎을 상대 머리와 팔 사이에 넣는다','팔꿈치를 몸에 붙인 채 상대 손을 등 뒤로 올려 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.2 · §11.3', 9),
  ('side-control', 'arm-triangle', '암 트라이앵글 (헤드 앤 암)', 'Arm Triangle (Head and Arm Choke)', array['헤드 앤 암 초크','가타가타메']::text[], array['상대 팔을 머리 너머로 넘겨 목과 팔이 함께 잡히게 한다','한 팔을 상대 목 아래로 넣고 반대 손과 맞잡는다(또는 이두를 잡는다)','머리를 상대 팔 바깥쪽에 붙여 팔이 빠지지 않게 한다','반대쪽으로 넘어가 다리를 벌리고 어깨를 눌러 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.8', 10),
  ('side-control', 'darce-choke', '다스 초크', 'D''Arce Choke', array['다스','다르스']::text[], array['상대가 쉬림프하며 언더훅을 잡으려 할 때 그 팔 아래로 내 팔을 넣는다','넣은 팔을 상대 목 반대편까지 깊게 꿰어 넣는다','반대 팔의 이두를 잡아 8자(피겨 포)를 만들고 상대 머리를 아래로 누른다','먼 쪽 엉덩이로 눕듯 몸을 낮춰 가슴으로 머리와 팔을 함께 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.2 · §9.3', 11),
  ('mount', 'mount-maintain', '마운트 유지', 'Mount Maintenance', array['그레이프바인','마운트 잡기']::text[], array['무릎을 상대 겨드랑이 가까이 올리고 엉덩이를 낮춘다','상대가 브릿지하면 그쪽으로 손을 짚어 균형을 잡는다','발을 상대 다리 안쪽으로 감아(그레이프바인) 엉덩이 빼기를 막는다','한 팔로 크로스페이스를 걸어 얼굴을 돌려 두면 상대가 반응해 공격 기회가 생긴다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §7.1 · BJJGraph mount/top 1위', 1),
  ('mount', 'mount-escape-upa', '마운트 이스케이프 (업파)', 'Mount Escape (Upa / Trap and Roll)', array['업파','브릿지 앤 롤','트랩 앤 롤']::text[], array['상대 한 팔과 같은 쪽 발을 묶는다(트랩)','발을 엉덩이 가까이 당겨 세운다','묶은 쪽으로 다리를 뻗으며 브릿지한다','굴러 넘겨 가드 안에 자리 잡는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/bottom 2위', 2),
  ('mount', 'mount-escape-elbow', '마운트 이스케이프 (엘보)', 'Elbow Escape from Mount', array['니 투 엘보','쉬림프 이스케이프']::text[], array['마운트 아래에서 팔꿈치로 상대 무릎이나 골반에 프레임을 만든다','한쪽 엉덩이를 빼며(쉬림프) 공간을 만든다','같은 쪽 무릎을 상대 다리 아래로 넣어 빼낸다','반대쪽도 같은 방법으로 빼서 하프가드나 클로즈드 가드로 돌아온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/bottom 1위', 3),
  ('mount', 'technical-mount', '테크니컬 마운트 (S 마운트)', 'Technical Mount / S-Mount', array['S 마운트','하이 마운트']::text[], array['상대가 옆으로 돌면 그쪽 무릎을 상대 등 뒤에 붙인다','반대 다리는 상대 머리 옆에 발을 세워 무릎을 높인다','가슴으로 상대 어깨를 눌러 등이 바닥에서 뜨지 않게 한다','여기서 암바 · 백 테이크 · 초크를 고른다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §7.2 · BJJGraph mount/top', 4),
  ('mount', 'mount-armbar', '마운트 암바', 'Armbar from Mount', array['마운트에서 암바']::text[], array['상대 한 팔을 가슴에 붙여 잡고 반대 손은 바닥을 짚는다','잡은 팔 쪽 무릎을 상대 머리 옆으로 올려 S 자세로 앉는다','반대 다리를 상대 얼굴 위로 넘기며 뒤로 눕는다 — 다리를 펴지 말고 상대를 몸 쪽으로 조인다','무릎을 모으고 엄지가 위로 가게 손목을 잡은 뒤 엉덩이를 들어 팔꿈치를 편다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §7.2', 5),
  ('mount', 'mount-cross-collar-choke', '크로스 칼라 초크 (마운트)', 'Cross Collar Choke from Mount', array['마운트 크로스 초크']::text[], array['마운트에서 한 손을 상대 깃 깊숙이 넣는다(손바닥 위로)','반대 손을 첫 손 아래로 교차해 반대 깃을 잡는다','상체를 숙여 머리를 상대 머리 옆 바닥 가까이 둔다','팔꿈치를 바닥 쪽으로 벌리며 손목을 비틀어 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기 2위)', 6),
  ('mount', 'ezekiel-choke', '에제키엘 초크', 'Ezekiel Choke', array['이지키엘','소매 초크']::text[], array['마운트에서 한 팔을 상대 머리 아래로 넣는다','반대 손으로 넣은 팔의 소매 안쪽을 잡는다','자유로운 손의 손날을 상대 목 앞으로 가로질러 넣는다','소매를 당기고 손날을 밀며 팔꿈치를 모아 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기)', 7),
  ('mount', 'mount-americana', '아메리카나 (마운트)', 'Americana from Mount', array['마운트 키락']::text[], array['상대 손목을 바닥에 눌러 팔꿈치가 90도가 되게 한다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','가슴을 낮춰 상대 어깨를 바닥에 고정한다','손목은 바닥에 붙인 채 팔꿈치를 들어 올려 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.4', 8),
  ('mount', 'gift-wrap', '기프트 랩 → 백 테이크', 'Gift Wrap to Back Control', array['기프트랩']::text[], array['상대가 옆으로 돌 때 머리 뒤로 팔을 넣어 상대 손목을 잡는다','상대 반대 팔을 그 손에 넘겨 잡아 팔이 얼굴을 가로지르게 한다','반대 손은 상대 팔 아래로 넣어 내 손목을 잡는다(기무라식 컨트롤)','다리를 상대 등 뒤로 넣고 그쪽으로 굴려 백 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §7.2', 9),
  ('back-control', 'back-control-maintain', '백 컨트롤 유지 (시트벨트 · 훅)', 'Back Control (Seatbelt & Hooks)', array['시트벨트','훅 넣기','백 잡기']::text[], array['한 팔은 상대 어깨 위, 반대 팔은 겨드랑이 아래로 넣어 손을 맞잡는다(시트벨트) — 조르는 손이 아래, 위 손이 덮는다','양 발을 상대 허벅지 안쪽에 넣는다(훅) — 아래쪽 훅이 더 중요','언더훅 팔꿈치는 몸에 붙이고 어깨 위 팔은 길게 감는다','상대가 빠지려 하면 위쪽 다리를 상대 골반 위로 넘기고 앉아 올라가 다시 잡는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §8.2~8.3', 1),
  ('back-control', 'rear-naked-choke', '리어 네이키드 초크', 'Rear Naked Choke', array['RNC','백 초크']::text[], array['시트벨트와 훅을 유지한 채 상대 손과 싸워 조르는 팔을 턱 아래로 밀어 넣는다','그 손을 반대 팔 이두에 걸고 반대 손은 상대 뒤통수에 둔다','가슴을 상대 등에 붙이고 턱을 당긴다','가슴을 펴며 팔꿈치를 모아 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §8.4 · BJJGraph back-control/top 1위', 2),
  ('back-control', 'bow-and-arrow-choke', '보우 앤 애로우 초크', 'Bow and Arrow Choke', array['활 조르기','보우앤애로우']::text[], array['백에서 한 손을 상대 깃 깊숙이 넣는다','반대 손으로 같은 쪽 상대 바지(무릎 안쪽)를 잡는다','깃 잡은 쪽 다리를 상대 어깨 위로 넘기며 옆으로 눕는다','깃을 당기고 다리로 밀어 활처럼 당겨 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph back-control/top (기 3위)', 3),
  ('back-control', 'body-triangle', '바디 트라이앵글', 'Body Triangle', array['보디 트라이앵글']::text[], array['백에서 한 다리를 상대 배 앞으로 가로질러 넣는다','그 발목을 반대 무릎 뒤에 걸어 삼각형으로 잠근다','시트벨트를 유지한 채 상대를 내 쪽으로 눕힌다','상대가 돌지 못하게 조이며 초크를 준비한다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph back-control/top', 4),
  ('back-control', 'back-escape', '백 이스케이프', 'Back Escape', array['백 빠져나오기','핸드 파이팅']::text[], array['턱을 당기고 양손으로 상대 조르는 팔을 잡아 막는다(핸드 파이팅)','상대 언더훅 반대쪽(조르는 팔 쪽)으로 어깨를 바닥에 붙이며 눕는다','엉덩이를 바닥 쪽으로 밀어 훅 하나를 빼낸다','상대 다리를 넘어 돌아서 가드나 사이드 탑으로 간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §8.3 · BJJGraph back-control/bottom', 5),
  ('turtle', 'turtle-basics', '터틀 (자세 · 방어)', 'Turtle (Basics & Defense)', array['거북이','터틀 자세']::text[], array['무릎과 팔꿈치를 바닥에 대고 팔꿈치를 무릎에 붙여 틈을 없앤다','턱을 당기고 손으로 목을 지켜 초크를 막는다','상대 먼 쪽 다리를 잡으려 하지 않는다(크루시픽스에 걸린다)','상대가 스프롤하면 그 공간으로 다리를 돌려 가드를 되찾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §10.6', 1),
  ('turtle', 'turtle-back-take', '터틀에서 백 테이크', 'Back Take from Turtle', array['터틀 백','거북이에서 백']::text[], array['상대 옆에서 가슴을 등에 붙이고 손으로 목을 위협해 상대 팔꿈치를 들게 한다','가까운 무릎을 상대 팔꿈치와 무릎 사이에 쐐기처럼 넣는다','반대 손으로 상대 먼 쪽 골반을 당겨 내 쪽으로 붙이고 반대 다리로 상대 다리 뒤를 건다(첫 훅)','상대가 옆으로 넘어가면 나머지 훅을 넣고 시트벨트를 잡는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §10.5 · BJJGraph turtle/top 1위', 2),
  ('turtle', 'turtle-flatten', '터틀 뒤집기 (사이드로)', 'Turtle Flatten to Side Control', array['터틀 브레이크다운']::text[], array['상대 옆에서 가까운 팔로 상대 먼 쪽 겨드랑이를 지나 손목을 잡는다','반대 손은 상대 가까운 무릎 뒤를 잡는다','손목을 당기고 무릎을 뽑으며 상대를 내 쪽으로 굴린다','등이 바닥에 닿으면 가슴을 붙여 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top 2위', 3),
  ('turtle', 'clock-choke', '클락 초크', 'Clock Choke', array['시계 초크']::text[], array['터틀 옆에서 한 손을 상대 깃 깊숙이 넣는다(엄지 안쪽)','반대 손으로 상대 가까운 손목이나 겨드랑이를 잡아 팔을 못 쓰게 한다','가슴을 상대 등 위에 싣고 다리를 상대 머리 쪽으로 걸어 돈다(시계 바늘처럼)','체중으로 눌러 깃이 목을 조이게 한다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 3위)', 4),
  ('turtle', 'sit-out', '싯아웃 (터틀 탈출)', 'Sit Out from Turtle', array['싯 아웃','싯스루']::text[], array['터틀에서 상대가 옆이나 뒤에 있을 때 가까운 쪽 손으로 상대 손목을 잡는다','반대 다리를 상대 반대편으로 길게 빼며 엉덩이를 바닥에 앉힌다','잡은 손목을 당기며 어깨로 상대 가슴을 밀어 뒤로 돌아간다','상대 뒤나 옆에 서서 백이나 탑 포지션으로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom 1위', 5),
  ('turtle', 'granby-roll', '그랜비 롤 (가드 회복)', 'Granby Roll to Guard', array['그랜비','어깨 구르기']::text[], array['터틀에서 상대 반대쪽 어깨를 바닥에 대고 턱을 당긴다','엉덩이를 들어 어깨 위로 둥글게 구른다','구르는 동안 다리를 상대 쪽으로 돌려 상대 몸을 향하게 한다','다리가 상대 앞에 오면 가드(오픈 · 클로즈드)로 잡는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom', 6)
) as t(position_slug, slug, name_ko, name_en, aliases, steps, is_reviewed, source, sort_order)
join public.positions p on p.slug = t.position_slug
on conflict (slug) do update set
  position_id = excluded.position_id,
  name_ko     = excluded.name_ko,
  name_en     = excluded.name_en,
  aliases     = excluded.aliases,
  steps       = excluded.steps,
  is_reviewed = excluded.is_reviewed,
  source      = excluded.source,
  sort_order  = excluded.sort_order;
